import { once } from 'lodash'
import app from './app'
import logger from './logger'
import { PORT } from './config'

const server = app.listen(PORT, () => {
  logger.info(`Listening at http://localhost:${PORT}`)
})

const gracefulShutdown = once((exitCode: number) => {
  logger.info('Server stopping...')

  server.close(() => {
    logger.info('Server stopped')
    // Leave time for logging / error capture
    setTimeout(() => process.exit(exitCode), 300)
  })

  // Forcibly shutdown after 8 seconds (Docker forcibly kills after 10 seconds)
  setTimeout(() => {
    logger.crit('Forcibly shutting down')
    // Leave time for logging / error capture
    setTimeout(() => process.exit(1), 300)
  }, 8000)
})

function handleUncaught(error: any, crashType: string): void {
  error.crashType = crashType
  logger.crit('😱  Server crashed', error)
}

process.on('uncaughtException', error => {
  handleUncaught(error, 'uncaughtException')
  gracefulShutdown(1)
})
process.on('unhandledRejection', error => {
  handleUncaught(error, 'unhandledRejection')
  gracefulShutdown(1)
})

// Termination signal sent by Docker on stop
process.on('SIGTERM', () => gracefulShutdown(0))
// Interrupt signal sent by Ctrl+C
process.on('SIGINT', () => gracefulShutdown(0))

import { SVG } from "./svg.js";
import type { Renderable } from "./types.js";

export type VerwaltungsstufeId =
  "gemeinde" | "kreis" | "bezirk" | "land" | "brd" | "eu";

export type Verwaltungsstufe = Renderable & {
  id: VerwaltungsstufeId;
  label: string;
};

function stern(svg: SVG) {
  return svg.path("M5,0 v10 M9.33,7.5 L0.67,2.5 M9.33,2.5 L0.67,7.5");
}

function defineStern(svg: SVG) {
  return svg.def(
    stern(svg).attr("transform", "scale(0.8)").attr("id", "tz_stern"),
  );
}

function sterne(count: number): Pick<Verwaltungsstufe, "size" | "render"> {
  return {
    size: [9 * count - 1, 9],
    render: (svg: SVG) => {
      const g = defineStern(svg).g();
      for (let i = 0; i < count; i++) {
        g.push(svg.use("#tz_stern").attr("x", 9 * i));
      }
      return g;
    },
  };
}

