#[macro_use]
extern crate lazy_static;
extern crate itertools;
extern crate regex;

use itertools::Itertools;
use regex::Regex;

macro_rules! some {
    ($expression:expr) => (match $expression {
        Some(value) => value,
        None => return None,
    })
}

fn most_common(name: &str) -> String {
    name.chars()
            .filter(|&x| x != '-')
            .sorted()
            .into_iter()
            .group_by(|&x| x)
            .into_iter()
            .map(|(k, v)| (k, v.count()))
            .sorted_by(|a, b| Ord::cmp(&b.1, &a.1))
            .into_iter()
            .map(|x| x.0)
            .take(5)
            .collect::<String>()[..5]
        .to_string()
}

struct Room {
    name: String,
    sector_id: usize,
    is_valid: bool,
}

fn parse_room(name: &str) -> Option<Room> {
    lazy_static! {
        static ref ROOM: Regex = Regex::new(r"((?:[a-z]+-)+)(\d+)\[([a-z]+)\]")
            .unwrap();
    }

    let captures = match ROOM.captures(name) {
        Some(x) => x,
        _ => return None,
    };

    let name = some!(captures.at(1));
    let name = &name[..(name.len() - 1)];

    let sector_id: usize = some!(captures.at(2).and_then(|x| x.parse().ok()));
    let checksum = some!(captures.at(3));

    let room = Room {
        name: name.to_string(),
        sector_id: sector_id,
        is_valid: most_common(name) == checksum,
    };

    Some(room)
}

fn solve_one(rooms: &[Room]) -> usize {
    rooms.iter().filter(|r| r.is_valid).fold(0, |acc, r| acc + r.sector_id)
}

fn solve_two(rooms: &[Room]) -> Option<usize> {
    const BASE: u8 = b'a';

    for room in rooms.iter().filter(|r| r.is_valid) {
        let key = (room.sector_id % 26) as u8;
        let decrypted = room.name
            .chars()
            .map(|c| match c {
                '-' => ' ',
                _ => ((c as u8 + key - BASE) % 26 + BASE) as char,
            })
            .collect::<String>();

        if decrypted.contains("north") {
            return Some(room.sector_id);
        }
    }

    None
}

fn main() {
    let rooms: Vec<_> = include_str!("../input")
        .trim()
        .lines()
        .filter_map(|r| parse_room(r))
        .collect();

    println!("[1] The sum of valid rooms is {}.", solve_one(&rooms));

    match solve_two(&rooms) {
        Some(id) => println!("[2] The objects are stored in room {}.", id),
        _ => println!("[2] Cannot find the room where the objects are stored."),
    }
}

use std::collections::{hash_map::Entry, HashMap};

use anyhow::anyhow;

struct Edge(String, String);
fn parse_input(input: &str) -> anyhow::Result<CaveMap> {
    let edges: Vec<Edge> = input
        .trim()
        .lines()
        .map(|line| {
            let (src, dst) = line
                .trim()
                .split_once('-')
                .ok_or_else(|| anyhow!("invalid edge: {}", line))?;
            Ok(Edge(src.to_owned(), dst.to_owned()))
        })
        .collect::<anyhow::Result<_>>()?;
    Ok(adjacency_matrix(&edges))
}

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
enum Cave {
    Start,
    End,
    Small,
    Big,
}
impl Cave {
    fn classify(name: &str) -> Cave {
        if name.chars().next().unwrap().is_ascii_uppercase() {
            Cave::Big
        } else {
            Cave::Small
        }
    }
}
struct CaveMap {
    caves: Vec<Cave>,
    conns: Vec<Vec<usize>>,
}
const START: usize = 0;
const END: usize = 1;
fn adjacency_matrix(edges: &[Edge]) -> CaveMap {
    let mut registry = HashMap::new();
    let mut caves = Vec::new();
    let mut conns = Vec::new();

    registry.insert("start".to_owned(), START);
    caves.push(Cave::Start);
    conns.push(Vec::new());

    registry.insert("end".to_owned(), END);
    caves.push(Cave::End);
    conns.push(Vec::new());

    for Edge(a, b) in edges {
        let a = match registry.entry(a.to_owned()) {
            Entry::Occupied(occ) => *occ.get(),
            Entry::Vacant(vac) => {
                let n = caves.len();
                vac.insert(n);
                caves.push(Cave::classify(a));
                conns.push(Vec::new());
                n
            }
        };
        let b = match registry.entry(b.to_owned()) {
            Entry::Occupied(occ) => *occ.get(),
            Entry::Vacant(vac) => {
                let n = caves.len();
                vac.insert(n);
                caves.push(Cave::classify(b));
                conns.push(Vec::new());
                n
            }
        };
        conns[a].push(b);
        conns[b].push(a);
    }
    CaveMap { caves, conns }
}

fn solve1(adj: &CaveMap) -> u64 {
    let mut vis = vec![0; adj.caves.len()];
    count_paths(START, &adj, &mut vis, 0)
}
fn solve2(adj: &CaveMap) -> u64 {
    let mut vis = vec![0; adj.caves.len()];
    count_paths(START, &adj, &mut vis, 1)
}

fn count_paths(cur: usize, adj: &CaveMap, vis: &mut [usize], allowed_repeats: usize) -> u64 {
    let mut count = 0;
    for &neighbor in &adj.conns[cur] {
        count += match adj.caves[neighbor] {
            Cave::Start => 0,
            Cave::End => 1,
            Cave::Big => count_paths(neighbor, adj, vis, allowed_repeats),
            Cave::Small => {
                if allowed_repeats == 0 && vis[neighbor] > 0 {
                    0
                } else {
                    let allowed_repeats = if vis[neighbor] == 0 {
                        allowed_repeats
                    } else {
                        allowed_repeats - 1
                    };
                    vis[neighbor] += 1;
                    let c = count_paths(neighbor, adj, vis, allowed_repeats);
                    vis[neighbor] -= 1;
                    c
                }
            }
        }
    }
    count
}

