pub fn start(
    block_headers_bytes: Arc<Mutex<Vec<u8>>>,
    config: &Config,
) {
    let start = Instant::now();

    let genesis_block_hash =
        String::from("000000000019d6689c085ae165831e934ff763ae46a2a6c172b3f1b60a8ce26f");
    let mut block_hash: String = genesis_block_hash.clone();
    let mut last_block: usize = 0;
    let mut min_block_hash: String = genesis_block_hash;

    let mut synced_height: usize = 0;
    let mut block_headers_map = HashMap::new();

    loop {
        let r = bitcoin::rpc::get_block_header(
            block_hash.clone(),
            &config,
        );
        match r {
            Ok(block_header_rpc_response) => {
                let block_header_rpc: bitcoin::rpc::BlockHeaderRpc =
                    block_header_rpc_response.result;
                let height = block_header_rpc.height.clone() as usize;
                if last_block == 0 && height % 1000 == 0 {
                    println!(
                        "Block #{} with hash {} elapsed {} seconds",
                        height,
                        block_hash,
                        start.elapsed().as_secs()
                    );
                    synced_height = sync(
                        &mut block_headers_map,
                        &block_headers_bytes,
                        height,
                        synced_height,
                    );
                }

                let block_hash_option = block_header_rpc.nextblockhash.clone();
                let sleep = match block_hash_option {
                    Some(val) => {
                        block_hash = val;
                        let block_header = BlockHeader::from_block_header_rpc(block_header_rpc);

                        block_headers_map.insert(height, block_header);
                        let hash_hex = block_header.hash_be().to_hex();
                        if min_block_hash > hash_hex {
                            min_block_hash = hash_hex;
                            println!("Block #{} with hash {} is the min!", height, min_block_hash);
                        }

                        false
                    }
                    None => {
                        if height != last_block {
                            synced_height = sync(
                                &mut block_headers_map,
                                &block_headers_bytes,
                                height,
                                synced_height,
                            );
                            println!(
                                "Block #{} with hash {} synced_height {}",
                                height,
                                block_hash,
                                synced_height
                            );
                        }
                        last_block = height;
                        block_hash = block_headers_map
                            .get(&(height - 6))
                            .unwrap()
                            .hash_be()
                            .to_hex(); //going back 6 blocks to support reorgs

                        true
                    }
                };

                if sleep {
                    thread::sleep(Duration::from_secs(60));
                }
            }
            Err(e) => {
                println!("{:?} with hash {}", e, block_hash);
                thread::sleep(Duration::from_secs(10));
            }
        }
    }
}

fn sync(
    block_headers_map: &mut HashMap<usize, BlockHeader>,
    block_headers_bytes: &Arc<Mutex<Vec<u8>>>,
    height: usize,
    synced_height: usize,
) -> usize {
    let sync_to_option = height.checked_sub(6);
    match sync_to_option {
        Some(sync_to) => {
            let mut block_headers_bytes_lock = block_headers_bytes.lock().unwrap();
            for i in synced_height..sync_to {
                match i % 2016 {
                    0 => block_headers_bytes_lock
                        .extend(block_headers_map.remove(&i).unwrap().as_bytes().into_iter()),
                    _ => block_headers_bytes_lock.extend(
                        block_headers_map
                            .remove(&i)
                            .unwrap()
                            .as_compressed_bytes()
                            .into_iter(),
                    ),
                }
            }
            sync_to
        }
        None => synced_height,
    }
}

use elf_rs::*;

pub struct RVElf<'a> {
    elf: Elf<'a>,
}

impl<'a> RVElf<'a> {
    pub fn decode_from(elf_buf: &'a [u8]) -> Option<Self> {
        let elf = match Elf::from_bytes(&elf_buf) {
            Ok(elf) => elf,
            Err(_) => return None,
        };

        Some(Self { elf })
    }

    pub fn entry_point(&self) -> u64 {
        self.elf.entry_point()
    }

    pub fn get_section(&self, name: &str) -> Option<(u64, &[u8])> {
        let name = name.as_bytes();
        let section = match self.elf.lookup_section(name) {
            Some(section) => section,
            None => return None,
        };
        Some((section.addr(), section.content()))
    }

    pub fn is_64bits(&self) -> bool {
        let hdr = self.elf.elf_header();
        let bit = hdr.class();
        return match bit {
            ElfClass::Elf32 => false,
            ElfClass::Elf64 => true,
            _ => panic!(),
        };
    }

    pub fn symbol_at(&self, addr: u64) -> Option<String> {
        let symtab = match self.get_section(".symtab") {
            Some((_, section)) => section,
            None => return None,
        };
        let srttab = match self.get_section(".strtab") {
            Some((_, section)) => section,
            None => return None,
        };
        if self.is_64bits() {
            self.symbol64_at(addr, symtab, srttab)
        } else {
            self.symbol32_at(addr, symtab, srttab)
        }
    }

    pub fn symbol32_at(&self, addr: u64, symtab: &[u8], strtab: &[u8]) -> Option<String> {
        let mut symtab = symtab;
        while symtab.len() > 15 {
            let w0 = symtab[0] as u64;
            let w1 = symtab[1] as u64;
            let w2 = symtab[2] as u64;
            let w3 = symtab[3] as u64;
            let wname = w0 | (w1 << 8) | (w2 << 16) | (w3 << 24);
            if wname != 0 {
                let w0 = symtab[4] as u64;
                let w1 = symtab[5] as u64;
                let w2 = symtab[6] as u64;
                let w3 = symtab[7] as u64;
                let wvalue = w0 | (w1 << 8) | (w2 << 16) | (w3 << 24);
                if wvalue == addr {
                    let wname = wname as usize;
                    let wname = crate::cstr::str_from_null_terminated_utf8_safe(&strtab[wname..]);
                    return Some(String::from(wname));
                }
            }
            symtab = &symtab[16..];
        }

        None
    }

    pub fn symbol64_at(&self, addr: u64, symtab: &[u8], strtab: &[u8]) -> Option<String> {
        let mut symtab = symtab;
        while symtab.len() > 23 {
            let w0 = symtab[0] as u64;
            let w1 = symtab[1] as u64;
            let w2 = symtab[2] as u64;
            let w3 = symtab[3] as u64;
            let wname = w0 | (w1 << 8) | (w2 << 16) | (w3 << 24);
            if wname != 0 {
                let w0 = symtab[8 + 0] as u64;
                let w1 = symtab[8 + 1] as u64;
                let w2 = symtab[8 + 2] as u64;
                let w3 = symtab[8 + 3] as u64;
                let w4 = symtab[8 + 4] as u64;
                let w5 = symtab[8 + 5] as u64;
                let w6 = symtab[8 + 6] as u64;
                let w7 = symtab[8 + 7] as u64;
                #[cfg_attr(rustfmt, rustfmt_skip)]
                let wvalue = w0 | (w1 << 8) | (w2 << 16) | (w3 << 24) |
                    (w4 << 32) | (w5 << 40) | (w6 << 48) | (w7 << 56);
                if wvalue == addr {
                    let wname = wname as usize;
                    let wname = crate::cstr::str_from_null_terminated_utf8_safe(&strtab[wname..]);
                    return Some(String::from(wname));
                }
            }
            symtab = &symtab[24..];
        }

        None
    }
}

